<script setup lang="ts">
import { ref, computed } from 'vue'
import { Calculator, FilePlus2, RotateCcw, BadgeCheck } from 'lucide-vue-next'
import { dealsApi, proposalsApi } from '../api/client'
import SectionTitle from '../components/SectionTitle.vue'
import BaseModal from '../components/BaseModal.vue'
import { useAppStore } from '../stores/app'
const app=useAppStore()
const form=ref({company_id:'',project_id:'',service_name:'',quantity:1,unit_price:0,discount:0,term_months:12,notes:''})
const errors=ref<Record<string,string>>({}),saving=ref(false),showResult=ref(false),result=ref<any>(null),showProposal=ref(false),proposalTitle=ref('')
const subtotal=computed(()=>Math.max(0,Number(form.value.quantity||0)*Number(form.value.unit_price||0)))
const discountAmount=computed(()=>subtotal.value*Math.min(100,Math.max(0,Number(form.value.discount||0)))/100)
const total=computed(()=>subtotal.value-discountAmount.value)
const monthly=computed(()=>total.value/Math.max(1,Number(form.value.term_months||1)))
const money=(n:number)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(n||0)
function validate(){const e:Record<string,string>={};if(!form.value.service_name.trim())e.service_name='Укажите услугу';if(!Number.isFinite(form.value.quantity)||form.value.quantity<1)e.quantity='Количество должно быть не меньше 1';if(!Number.isFinite(form.value.unit_price)||form.value.unit_price<0)e.unit_price='Цена не может быть отрицательной';if(form.value.discount<0||form.value.discount>100)e.discount='Скидка должна быть от 0 до 100%';if(form.value.term_months<1)e.term_months='Срок должен быть не меньше 1 месяца';errors.value=e;return !Object.keys(e).length}
async function calculate(){if(!validate())return;saving.value=true;try{result.value=await dealsApi.create({...form.value,subtotal:subtotal.value,discount_amount:discountAmount.value,total:total.value,monthly_payment:monthly.value});showResult.value=true;app.notify('Расчёт сделки сохранён в backend')}catch(e:any){app.notify(`Ошибка сохранения: ${e.userMessage||'проверьте API'}`)}finally{saving.value=false}}
async function createProposal(){if(!result.value?.id){app.notify('Backend не вернул ID сделки — невозможно связать предложение');return}saving.value=true;try{const p=await proposalsApi.create({title:proposalTitle.value||`Коммерческое предложение — ${form.value.service_name}`,deal_id:result.value.id,company_id:form.value.company_id||undefined,status:'draft'});showProposal.value=false;app.notify(`Коммерческое предложение создано${p?.id?` (№ ${p.id})`:''}`)}catch(e:any){app.notify(`Не удалось создать предложение: ${e.userMessage||'ошибка API'}`)}finally{saving.value=false}}
function reset(){form.value={company_id:'',project_id:'',service_name:'',quantity:1,unit_price:0,discount:0,term_months:12,notes:''};errors.value={};result.value=null;showResult.value=false}
</script>
<template><main class="page"><SectionTitle title="Калькулятор сделок" subtitle="Рассчитайте коммерческие параметры и сохраните результат в системе."/><div class="calculator-layout"><section class="panel calculator-form"><div class="panel-heading"><div><h2>Параметры сделки</h2><p>Поля со звёздочкой обязательны</p></div><div class="calc-heading-icon"><Calculator/></div></div><form @submit.prevent="calculate"><div class="form-grid"><label class="field full"><span>Наименование услуги или продукта *</span><input v-model="form.service_name" placeholder="Например, облачная инфраструктура"/><small v-if="errors.service_name" class="field-error">{{errors.service_name}}</small></label><label class="field"><span>ID компании (если известен)</span><input v-model="form.company_id" placeholder="ID из backend"/></label><label class="field"><span>ID проекта (если известен)</span><input v-model="form.project_id" placeholder="ID из backend"/></label><label class="field"><span>Количество *</span><input v-model.number="form.quantity" type="number" min="1"/><small v-if="errors.quantity" class="field-error">{{errors.quantity}}</small></label><label class="field"><span>Цена за единицу, ₽ *</span><input v-model.number="form.unit_price" type="number" min="0" step="0.01"/><small v-if="errors.unit_price" class="field-error">{{errors.unit_price}}</small></label><label class="field"><span>Скидка, %</span><input v-model.number="form.discount" type="number" min="0" max="100"/><small v-if="errors.discount" class="field-error">{{errors.discount}}</small></label><label class="field"><span>Срок, месяцев</span><input v-model.number="form.term_months" type="number" min="1"/><small v-if="errors.term_months" class="field-error">{{errors.term_months}}</small></label><label class="field full"><span>Комментарий к расчёту</span><textarea v-model="form.notes" rows="3" placeholder="Дополнительные условия, ограничения…"/></label></div><div class="form-actions"><button type="button" class="btn btn-secondary" @click="reset"><RotateCcw :size="16"/> Очистить</button><button class="btn btn-primary" :disabled="saving"><Calculator :size="16"/>{{saving?'Сохраняем…':'Рассчитать и сохранить'}}</button></div></form></section><aside class="calculation-aside"><section class="result-card"><div class="result-top"><span>Предварительный расчёт</span><div class="result-icon"><Calculator/></div></div><div class="result-total">{{money(total)}}</div><p>Итоговая стоимость с учётом скидки</p><div class="result-divider"></div><div class="result-line"><span>Стоимость до скидки</span><strong>{{money(subtotal)}}</strong></div><div class="result-line"><span>Скидка ({{form.discount||0}}%)</span><strong class="discount-value">− {{money(discountAmount)}}</strong></div><div class="result-line"><span>Срок договора</span><strong>{{form.term_months}} мес.</strong></div><div class="result-line"><span>В среднем за месяц</span><strong>{{money(monthly)}}</strong></div><div class="result-foot"><BadgeCheck :size="16"/> Значения обновляются автоматически</div></section><section class="panel comparison-panel"><h3>Сравнение цен</h3><p>Введите параметры для расчёта. Сравнение с тарифами и рыночными предложениями подключается через отдельный endpoint backend.</p><div class="comparison-placeholder">Нет подключённых ценовых ориентиров</div></section></aside></div><section v-if="showResult" class="panel saved-result"><div class="saved-check"><BadgeCheck/></div><div><h3>Расчёт сохранён</h3><p>Backend создал запись сделки. Вы можете сформировать коммерческое предложение на основе её ID.</p><small>ID сделки: {{result?.id??'не возвращён'}}</small></div><button class="btn btn-primary" @click="showProposal=true"><FilePlus2 :size="16"/> Создать КП</button></section><BaseModal v-if="showProposal" title="Новое коммерческое предложение" @close="showProposal=false"><form @submit.prevent="createProposal"><label class="field"><span>Название предложения</span><input v-model="proposalTitle" :placeholder="`КП — ${form.service_name}`"/></label><p class="modal-note">Предложение будет сохранено через POST /api/proposals и связано с созданной сделкой.</p><div class="form-actions"><button type="button" class="btn btn-secondary" @click="showProposal=false">Отмена</button><button class="btn btn-primary" :disabled="saving">Создать через API</button></div></form></BaseModal></main></template>